import React, { useEffect, useState } from 'react';
import { createTm } from '../services/api';

export default function NewTmCreate({ onCreated, onCancel }) {
  const [date_tm, setDateTm] = useState()
  const [operating_time, setOperatingTime] = useState('')
  const [number_orderoutfit, setNumberOrder] = useState('')
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);

   // Данные для выпадашек (Зав.номер машины и сервисные компании)
  const [serviceCompanies, setServiceCompanies] = useState([]);
  const [serial, setSerial] = useState([]);
  const [selectedServiceCompanyId, setSelectedServiceCompanyId] = useState('');
  const [selectedSerial, setSelectedSerial] = useState([]);

    // Данные для справочников
  const [modelMachines, setModelMachines] = useState([]);
  const [type_of_tm, setType] = useState([]);
  const [tm_company, setTmCompany] = useState('')

  useEffect(() => {
    fetch('/api/service_companies/')
      .then(res => res.json())
      .then(data => setServiceCompanies(Array.isArray(data) ? data : []))
      .catch(() => setServiceCompanies([]));    
          
  }, []);

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    setError(null);
    const payload = {
      serial_number_machine: serial,
      model_machine: model,
      service_company: selectedServiceCompanyId || null,
      type_of_tm: type_of_tm,
      date_tm: date_tm,
      operating_time: operating_time,
      number_orderoutfit: number_orderoutfit,
      tm_company: tm_company,
    };
    try {
      const res = await createTm(payload);
      setLoading(false);
      onCreated?.(res);
    } catch (err) {
      setLoading(false);
      setError(err?.message || 'Ошибка при создании');
    }
  };

  return (
    <div className="new-machine-create" style={{ border: '1px solid #ccc', padding: 16, borderRadius: 6, margin: '12px 0' }}>
      <h3>Создать новое ТО</h3>
      <form onSubmit={handleSubmit} style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
        <input placeholder="Серийный номер" value={serial} onChange={(e) => setSerial(e.target.value)} required />
        <input placeholder="Модель машины" value={model} onChange={(e) => setModel(e.target.value)} required />
        <input placeholder="Вид ТО" value={type_of_tm} onChange={(e) => setType(e.target.value)} required />
        <input placeholder="Дата проведения ТО" value={date_tm} onChange={(e) => setDateTm(e.target.value)} required />
        <input placeholder="Номер заказа-наряда" value={number_orderoutfit} onChange={(e) => setNumberOrder(e.target.value)} required />
        <input placeholder="Компания, проводившая ТО" value={tm_company} onChange={(e) => setTmCompany(e.target.value)} required />

        <select value={selectedServiceCompanyId} onChange={(e) => setSelectedServiceCompanyId(e.target.value)}>
          <option value="">Выберите сервисную компанию</option>
          {serviceCompanies.map((s) => (
            <option key={s.id} value={s.id}>{s.name}</option>
          ))}
        </select>

        <div style={{ display: 'flex', gap: 8 }}>
          <button type="submit" disabled={loading}>{loading ? 'Создание...' : 'Создать'}</button>
          <button type="button" onClick={onCancel} disabled={loading}>Отмена</button>
        </div>
        {error && <div style={{ color: 'red' }}>{error}</div>}
      </form>
    </div>
  );
}
